{
  "checks": [
    {
      "problem": "问题清单和下一步建议与链路明细之间只有编号和文字，没有指向具体截图的定位，读者要在几节之间长距离滚动、逐张数步骤才能找到对应界面。",
      "A": "部分解决",
      "B": "部分解决"
    },
    {
      "problem": "链路明细按产品上下分成几块铺开，不同产品的同一步骤不在同一水平线上，读者无法并排对照各产品在同一环节的做法，只能来回滚动查找。",
      "A": "没解决",
      "B": "没解决"
    }
  ],
  "worse": [
    {
      "version": "A",
      "where": "「问题清单」表下那一段依据小字，以及「下一步」每条建议的依据行",
      "why": "7 条问题的依据被压成表外一段小字，只能用 P1…P7 编号和上面各行对应，读者逐条核对“这条问题的依据是什么”时要在表格和表下小字之间上下找；「下一步」的依据又把 P 编号和“云途第 4 步·增值服务”这样的位置混写在同一串里，要先拆开哪段是编号、哪段是界面。B 版把产品、步骤、依据并进同一行，一条问题的位置、问题、严重度、依据一次读完。"
    }
  ],
  "better": "B",
  "reason": "两版在链路明细和问题定位上几乎一样，差别集中在问题清单/下一步：B 版把产品、步骤、依据并进同一行，读者逐条核对 7 个问题（页面上最常做的一节）时不用在表格与表下小字之间来回；A 版依据另起一段、下一步依据又混写编号与位置，读起来多拆一层，虽然下一步依据写得比 B 全，但只有 4 条，且 B 的 P 编号在紧邻上一节的表里就能查到。",
  "next": [
    {
      "where": "「链路明细」整节",
      "task": "横向比较四款 App 在同一步骤（选舱位、附加产品、乘机人、退改规则、确认支付）的界面做法",
      "why": "四款产品各自成块从上往下排，同一步骤不在同一水平线上，读者只能记住一款的做法再往下滚去找另一款的对应步骤，反复上下滚动；「关键环节对比」只有文字结论，替代不了并排看界面。"
    },
    {
      "where": "「问题明细」与「链路明细」之间",
      "task": "从 P1…P7 找到它对应的那张界面截图",
      "why": "两节之间没有图号或跳转，问题明细只写“云途·第 4 步”，读者要从页面底部滚回中部的链路明细，再在云途块里按“第 4 步”逐张找，长距离滚动和按步数图仍在。"
    },
    {
      "where": "「下一步」四条建议",
      "task": "核对某条建议到底依据了哪几张界面",
      "why": "依据只列 P1、P2、P4 这类编号（外加“飞鱼第 5 步”），读者要先回「问题明细」把编号换成产品和步骤，再滚到链路明细找图，一次核对要跨三节。"
    }
  ]
